import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u16")
C = "B1"
# Lições de aprofundamento (10–24): ortografia, pontuação e tipos de texto.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)
def N(id, nl, pt, art, pl=None): return V(id, nl, pt, "noun", art, pl)

L(10, "Ortografia: a regra do dt", "Hij wordt, word jij?",
  ["Aplicar a regra d/t/dt no presente"],
  vocab=[N("v-dt-regel","dt-regel","regra do dt","de"), N("v-werkwoordspelling","werkwoordspelling","ortografia dos verbos","de"),
         N("v-spelfout","spelfout","erro ortográfico","de","spelfouten")],
  ex=[("Hij wordt morgen dertig.","Ele faz trinta amanhã."),("Word jij ook moe van dit weer?","Também ficas cansado com este tempo?"),("Dat is een bekende spelfout.","Esse é um erro ortográfico conhecido.")],
  review=["v-spelling"],
  gram=[G("g-dt-regel","A regra do dt","No presente, junta-se **-t** ao radical com *hij/zij/het/u* e com *jij* **antes** do verbo: *ik word*, *jij wordt*, *hij wordt*. Se *jij/je* vem **depois** do verbo (pergunta, inversão), **não** há -t: *Word jij?* O radical de *worden* já termina em -d, por isso se escreve **dt**. Truque: substitui por *lopen* — *hij loopt* → *hij wordt*; *loop jij?* → *word jij?*",
    [("Hij vindt het leuk.","Ele acha giro."),("Vind jij het leuk?","Tu achas giro?")])],
  cefr=C, exs=[
    MA([("dt-regel","regra do dt"),("werkwoordspelling","ortografia dos verbos"),("spelfout","erro ortográfico"),("spelling","ortografia")], "Ortografia.", ["v-dt-regel","v-werkwoordspelling","v-spelfout","v-spelling"]),
    MC("Hij ___ morgen dertig.", ["*wordt","word|Falta o -t.","wort|O radical é «word»."], "hij + radical + t.", ["v-dt-regel"]),
    MC("___ jij ook moe?", ["*Word","Wordt|Com jij depois do verbo: sem -t.","Wort|Não."], "Inversão: sem -t.", ["v-dt-regel"]),
    MC("Jij ___ het toch ook leuk?", ["*vindt","vind|jij antes do verbo: com -t.","vint|Não."], "jij + radical + t.", ["v-dt-regel"]),
    FB("Wat ___ je ervan? (vinden)", ["vind"], "Inversão com je: sem -t.", ["v-dt-regel"], choices=["vind","vindt","vint"], tr="O que achas disso?"),
    FB("Het ___ steeds kouder. (worden)", ["wordt"], "het + t.", ["v-dt-regel"], choices=["wordt","word","werd"], tr="Está a ficar cada vez mais frio."),
    FE(["Wordt","jij","ook","dertig","dit","jaar?"], 0, "Word", "Inversão: sem -t.", ["v-dt-regel"]),
    FE(["Mijn","zus","antwoord","altijd","snel."], 2, "antwoordt", "zij (mijn zus) + t.", ["v-dt-regel"]),
    MC("O truque do «lopen» serve para…", ["*ouvir se há -t: «hij loopt» → «hij wordt»","conjugar no passado|Não.","escolher o artigo|Não."], "Truque.", ["v-werkwoordspelling"]),
  ], diff=4, mins=6)

L(11, "Ortografia: passado com -te ou -de", "'t Kofschip",
  ["Escolher -te/-de no passado e -t/-d no particípio"],
  vocab=[N("v-kofschip","'t kofschip","'t kofschip (regra mnemónica)","het"), X("v-zwak-werkwoord","zwak werkwoord","verbo fraco (regular)")],
  ex=[("Ik werkte gisteren tot zes uur.","Ontem trabalhei até às seis."),("We woonden vroeger in Porto.","Antigamente vivíamos no Porto."),("Ze heeft het pakketje gestuurd.","Ela enviou a encomenda.")],
  review=["v-werkwoordspelling","v-dt-regel"],
  gram=[G("g-kofschip","'t Kofschip","Nos verbos fracos, olha para a **última letra do radical**. Se for uma das consoantes de **'t kofschip** (t, k, f, s, ch, p), o passado leva **-te(n)** e o particípio **-t**: *werken → werkte, gewerkt*. Caso contrário, **-de(n)** e **-d**: *wonen → woonde, gewoond*. Atenção: em *leven → leefde* e *reizen → reisde* conta o v/z do infinitivo, por isso **-de**.",
    [("praten → praatte → gepraat","conversar"),("horen → hoorde → gehoord","ouvir")])],
  cefr=C, exs=[
    MA([("'t kofschip","regra -te/-de"),("zwak werkwoord","verbo fraco"),("werkte","trabalhou"),("woonde","morava")], "Passado.", ["v-kofschip","v-zwak-werkwoord","v-werkwoordspelling","v-dt-regel"]),
    MC("werken → ik ___", ["*werkte","werkde|k está em kofschip → -te.","werkt|Presente."], "k → -te.", ["v-kofschip"]),
    MC("wonen → wij ___", ["*woonden","woonten|n não está em kofschip.","woonde|Plural: -den."], "n → -de(n).", ["v-kofschip"]),
    MC("leven → hij ___", ["*leefde","leefte|Conta o v do infinitivo → -de.","leeft|Presente."], "Exceção aparente: v/z.", ["v-kofschip"]),
    CJ("praten","we","Gisteren ___ we urenlang.", ["praatten"], "praat + ten.", ["v-kofschip"], tense="passado-simples"),
    CJ("sturen","zij","Ze heeft me een kaartje ___.", ["gestuurd"], "r → -d.", ["v-kofschip"], tense="passado-perfeito"),
    FB("Ik heb de hele dag ___. (fietsen)", ["gefietst"], "s → -t.", ["v-kofschip"], choices=["gefietst","gefietsd","fietste"], tr="Andei de bicicleta o dia todo."),
    FE(["We","verhuisden","in","2020","en","we","woonte","eerst","in","Leiden."], 6, "woonden", "n → -de(n); plural.", ["v-kofschip"]),
    TR("pt-nl","Ontem trabalhei até às seis.", ["Ik werkte gisteren tot zes uur","Gisteren werkte ik tot zes uur","Ik heb gisteren tot zes uur gewerkt"], "werkte.", ["v-kofschip"]),
  ], diff=4, mins=6)

L(12, "Ortografia: vogais longas e curtas", "Maan → manen, man → mannen.",
  ["Escrever o plural com vogal simples ou dupla e consoante dobrada"],
  vocab=[N("v-lettergreep","lettergreep","sílaba","de","lettergrepen"), X("v-open-lettergreep","open lettergreep","sílaba aberta")],
  ex=[("Boom heeft in het meervoud één o: bomen.","«Boom» tem no plural um só o: bomen."),("Bij «man» verdubbel je de n: mannen.","Em «man» dobra-se o n: mannen.")],
  review=["v-spelling"],
  gram=[G("g-lettergreep","Vogal longa ou curta","Uma sílaba que **acaba em vogal** (aberta) já soa longa, por isso escreve-se com **uma** vogal: *maan → ma-nen*, *boom → bo-men*. Uma vogal **curta** precisa de uma sílaba fechada, por isso **dobra-se a consoante**: *man → man-nen*, *bus → bus-sen*, *pot → pot-ten*.",
    [("straat → straten","rua → ruas"),("kat → katten","gato → gatos")])],
  cefr=C, exs=[
    MA([("lettergreep","sílaba"),("open lettergreep","sílaba aberta"),("bomen","árvores"),("mannen","homens")], "Sílabas.", ["v-lettergreep","v-open-lettergreep","v-spelling"]),
    MC("Plural de «straat»:", ["*straten","straaten|Sílaba aberta: uma só vogal.","stratten|Não."], "Vogal longa.", ["v-open-lettergreep"]),
    MC("Plural de «kat»:", ["*katten","katen|Isso soaria com a longo.","kats|Não."], "Vogal curta → consoante dupla.", ["v-lettergreep"]),
    MC("Plural de «been» (perna):", ["*benen","beenen|Uma só vogal.","bennen|Mudaria o som."], "Sílaba aberta.", ["v-open-lettergreep"]),
    FB("Er staan drie ___ in de tuin. (boom)", ["bomen"], "bo-men.", ["v-open-lettergreep"], choices=["bomen","boomen","bommen"], tr="Há três árvores no jardim."),
    FB("Er rijden geen ___ meer. (bus)", ["bussen"], "Consoante dupla.", ["v-lettergreep"], choices=["bussen","busen","buss"], tr="Já não há autocarros."),
    FE(["Er","lopen","twee","kaatten","in","de","straat."], 3, "katten", "Vogal curta: katten.", ["v-lettergreep"]),
    FE(["De","straaten","zijn","nat."], 1, "straten", "Sílaba aberta: straten.", ["v-open-lettergreep"]),
    MC("O mesmo princípio vale para verbos: «maken» escreve-se com um a porque…", ["*ma-ken: sílaba aberta","é irregular|Não.","é estrangeiro|Não."], "Mesma regra.", ["v-open-lettergreep"]),
  ], diff=4, mins=6)

L(13, "Palavras compostas", "Pannenkoek, boekenkast, koffiekopje.",
  ["Escrever compostos juntos e usar o -n- de ligação"],
  vocab=[N("v-samenstelling","samenstelling","palavra composta","de","samenstellingen"), X("v-aan-elkaar-schrijven","aan elkaar schrijven","escrever junto")],
  ex=[("In het Nederlands schrijf je samenstellingen aan elkaar.","Em neerlandês escrevem-se os compostos juntos."),("Een boekenkast is een kast voor boeken.","Uma estante é um armário para livros.")],
  review=["v-spelling","v-spelfout"],
  gram=[G("g-samenstelling","Compostos","Os compostos escrevem-se **juntos**: *koffiekopje*, *fietsenstalling*, *zorgverzekering* (escrever *koffie kopje* separado é um erro muito comum). O **último** elemento dá o significado e o artigo: *het kopje → het koffiekopje*. Entre as partes aparece muitas vezes **-en-** ou **-s-**: *pannenkoek*, *boekenkast*, *verjaardagstaart*.",
    [("de taart → de verjaardagstaart","o bolo de aniversário"),("het huis → het ziekenhuis","o hospital")])],
  cefr=C, exs=[
    MA([("samenstelling","palavra composta"),("aan elkaar schrijven","escrever junto"),("boekenkast","estante"),("pannenkoek","panqueca")], "Compostos.", ["v-samenstelling","v-aan-elkaar-schrijven","v-spelling","v-spelfout"]),
    MC("Qual está bem escrito?", ["*zorgverzekering","zorg verzekering|Separado é erro.","zorg-verzekering|Sem hífen aqui."], "Junto.", ["v-aan-elkaar-schrijven"]),
    MC("Artigo de «koffiekopje»:", ["*het (het kopje)","de (de koffie)|Conta o último elemento.","depende|Não."], "Último elemento.", ["v-samenstelling"]),
    AR("verjaardagstaart", "bolo de aniversário", "de", "de taart → de verjaardagstaart.", ["v-samenstelling"]),
    FB("Zet de boeken maar in de ___.", ["boekenkast"], "Composto.", ["v-samenstelling"], choices=["boekenkast","boeken kast","boekkast"], tr="Põe os livros na estante."),
    FE(["Ik","heb","een","nieuwe","fiets","bel","gekocht."], 4, "fietsbel", "Composto: fietsbel (sem espaço).", ["v-aan-elkaar-schrijven"]),
    FE(["We","eten","vanavond","pannekoeken."], 3, "pannenkoeken", "Com -n-: pannenkoeken.", ["v-samenstelling"]),
    TR("pt-nl","Escrevem-se os compostos juntos.", ["Je schrijft samenstellingen aan elkaar","Samenstellingen schrijf je aan elkaar"], "aan elkaar.", ["v-aan-elkaar-schrijven"]),
    MC("Porque se diz que o neerlandês tem palavras «enormes»?", ["*Porque os compostos se juntam numa só palavra","Porque não usa artigos|Não.","Porque não tem espaços|Exagero."], "Ex.: arbeidsongeschiktheidsverzekering.", ["v-samenstelling"]),
  ], diff=4, mins=5)

L(14, "Pontuação e maiúsculas", "Maandag spreek ik Nederlands.",
  ["Usar maiúsculas, vírgulas e aspas como em neerlandês"],
  vocab=[N("v-hoofdletter","hoofdletter","maiúscula","de","hoofdletters"), N("v-uitroepteken","uitroepteken","ponto de exclamação","het"),
         N("v-aanhalingstekens","aanhalingstekens","aspas","de")],
  ex=[("Dagen en maanden schrijf je met een kleine letter: maandag, januari.","Dias e meses escrevem-se com minúscula."),("Talen schrijf je met een hoofdletter: Nederlands, Portugees.","As línguas escrevem-se com maiúscula."),("Zet de woorden tussen aanhalingstekens.","Põe as palavras entre aspas.")],
  review=[],
  cefr=C, exs=[
    MA([("hoofdletter","maiúscula"),("uitroepteken","ponto de exclamação"),("aanhalingstekens","aspas"),("komma","vírgula")], "Pontuação.", ["v-hoofdletter","v-uitroepteken","v-aanhalingstekens"]),
    MC("Em neerlandês, os nomes de línguas (Portugees, Nederlands)…", ["*escrevem-se com maiúscula","escrevem-se com minúscula, como em português|Em NL é diferente.","tanto faz|Não."], "Diferente do português!", ["v-hoofdletter"]),
    MC("Os dias da semana e os meses em neerlandês…", ["*escrevem-se com minúscula (maandag, januari)","escrevem-se com maiúscula|Não.","só os meses têm maiúscula|Não."], "Como em português.", ["v-hoofdletter"]),
    MC("Onde vai a vírgula? «Toen ik thuiskwam ___ was iedereen al weg.»", ["*depois de «thuiskwam»","depois de «Toen»|Não.","não há vírgula|Entre os dois verbos põe-se vírgula."], "Vírgula entre orações.", []),
    AR("uitroepteken", "ponto de exclamação", "het", "Het teken → het uitroepteken.", ["v-uitroepteken"]),
    MC("Qual destas palavras se escreve com maiúscula em neerlandês?", ["*Portugees (a língua)","dinsdag|Dia: minúscula.","augustus|Mês: minúscula."], "Línguas: maiúscula.", ["v-hoofdletter"]),
    FB("Zet een ___ aan het eind van een vraag.", ["vraagteken"], "Ponto de interrogação.", ["v-uitroepteken"], choices=["vraagteken","uitroepteken","komma"], tr="Põe um ponto de interrogação no fim de uma pergunta."),
    TR("pt-nl","Põe a palavra entre aspas.", ["Zet het woord tussen aanhalingstekens"], "tussen aanhalingstekens.", ["v-aanhalingstekens"]),
    MC("Nacionalidades e adjetivos de país («Portugese wijn»)…", ["*escrevem-se com maiúscula","com minúscula|Em NL, maiúscula.","tanto faz|Não."], "Portugese wijn, Nederlandse kaas.", ["v-hoofdletter"]),
  ], diff=3, mins=5)

L(15, "Carta de motivação", "Graag kom ik in aanmerking voor deze functie.",
  ["Escrever o início e o fim de uma carta de candidatura"],
  vocab=[N("v-motivatiebrief","motivatiebrief","carta de motivação","de","motivatiebrieven"), X("v-in-aanmerking-komen","in aanmerking komen voor","ser considerado para|candidatar-me a"),
         X("v-met-interesse","met veel interesse","com muito interesse")],
  ex=[("Met veel interesse las ik uw vacature op uw website.","Foi com muito interesse que li o vosso anúncio no vosso site."),("Graag kom ik in aanmerking voor deze functie.","Gostaria de ser considerado para esta função."),("Graag licht ik mijn motivatie toe in een gesprek.","Terei todo o gosto em explicar a minha motivação numa entrevista.")],
  review=["v-geachte","v-met-vriendelijke-groet","v-vacature","v-bijlage"],
  cefr=C, exs=[
    MA([("motivatiebrief","carta de motivação"),("in aanmerking komen voor","ser considerado para"),("met veel interesse","com muito interesse"),("bijlage","anexo")], "Candidatura.", ["v-motivatiebrief","v-in-aanmerking-komen","v-met-interesse","v-bijlage"]),
    MC("Uma boa primeira frase de uma carta de motivação:", ["*Met veel interesse las ik uw vacature voor de functie van receptionist.","Hoi! Ik wil die baan.|Informal demais.","Ik ben de beste.|Pouco profissional."], "Abertura.", ["v-met-interesse"]),
    TR("pt-nl","Gostaria de ser considerado para esta função.", ["Graag kom ik in aanmerking voor deze functie","Ik kom graag in aanmerking voor deze functie"], "in aanmerking komen.", ["v-in-aanmerking-komen"]),
    TR("pt-nl","Em anexo envio o meu CV.", ["In de bijlage stuur ik mijn cv","Als bijlage stuur ik mijn cv","In de bijlage vindt u mijn cv"], "bijlage.", ["v-bijlage"]),
    FB("Graag kom ik in aanmerking ___ deze functie.", ["voor"], "Preposição fixa.", ["v-in-aanmerking-komen"], choices=["voor","van","op"], tr="Gostaria de ser considerado para esta função."),
    FE(["Met","veel","interesse","ik","las","uw","vacature."], 3, "las", "Inversão: Met veel interesse las ik.", ["v-met-interesse"]),
    CO("text","Motivatiebrief (fragment)","Geachte heer De Vries,\n\nMet veel interesse las ik uw vacature voor een medewerker klantenservice. Ik woon sinds drie jaar in Nederland en spreek Portugees, Engels en Nederlands. In mijn vorige baan in Lissabon hielp ik dagelijks klanten via telefoon en e-mail. Graag kom ik in aanmerking voor deze functie en licht ik mijn motivatie toe in een gesprek.\n\nMet vriendelijke groet,\nAna Ferreira",
       [("Para que função?", ["*Apoio ao cliente","Receção de hotel","Contabilidade"]),("Que línguas fala?", ["*Português, inglês e neerlandês","Só neerlandês","Espanhol"]),("Como termina?", ["*Com vriendelijke groet","Groetjes","Liefs"])],
       "Carta modelo (fictícia).", ["v-motivatiebrief"]),
    SW("Escreva o primeiro parágrafo de uma carta de motivação (3–4 frases) para uma vaga que lhe interesse.", ["Geachte mevrouw Jansen,\n\nMet veel interesse las ik uw vacature voor een assistent in uw bibliotheek. Ik ben een nauwkeurig persoon en ik hou van boeken. Graag kom ik in aanmerking voor deze functie."], ["Saudação formal","Referência à vaga","in aanmerking komen"], 30, "Carta.", ["v-motivatiebrief","v-in-aanmerking-komen"]),
    LI("In de bijlage vindt u mijn cv.", ["In de bijlage vindt u mijn cv","In de bijlage vindt u mijn CV"], "Em anexo encontra o meu CV.", "Fórmula.", ["v-bijlage"]),
  ], diff=4, mins=7)

